entity Prob_6_35l_Up_Dwn_Beh_vhdl is	port (A: buffer bit_vector (3 downto 0); CLK, Up, Down, reset_b: bit);end Prob_6_35l_Up_Dwn_Beh_vhdl;architecture Behavioral of Prob_6_35l_Up_Dwn_Beh_vhdl isbegin  process  (CLK, reset_b) begin    if (reset_b = '0') then A <= "0000";    else case (Up & Down) is      when "10" =>	 A <= A + "0001";		// Up      when "01" =>  A <= A Ð "0001";		// Down      when others =>	A <= A;	// Suspend (Redundant statement)    end case; end  Behavioral;